import React,{useEffect,useState}from"react";
import{createRoot}from"react-dom/client";
import{createClient}from"@supabase/supabase-js";
import"./styles.css";
const supabase=createClient(import.meta.env.VITE_SUPABASE_URL,import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY);
const districtSectors={"Bugesera":["Gashora","Juru","Kamabuye","Mareba","Mayange","Musenyi","Mwogo","Ngeruka","Ntarama","Nyamata","Nyarugenge","Rilima","Ruhuha","Rweru","Shyara"],"Gatsibo":["Gasange","Gatsibo","Gitoki","Kabarore","Kageyo","Kiramuruzi","Kiziguro","Muhura","Murambi","Ngarama","Nyagihanga","Remera","Rugarama","Rwimbogo"],"Kayonza":["Gahini","Kabare","Kabarondo","Mukarange","Murama","Murundi","Mwiri","Ndego","Nyamirama","Rukara","Ruramira","Rwinkwavu"],"Kirehe":["Gahara","Gatore","Kigarama","Kigina","Kirehe","Mahama","Mpanga","Musaza","Mushikiri","Nasho","Nyamugari","Nyarubuye"],"Ngoma":["Gashanda","Jarama","Karembo","Kazo","Kibungo","Mugesera","Murama","Mutenderi","Remera","Rukira","Rukumberi","Rurenge","Sake","Zaza"],"Nyagatare":["Gatunda","Karama","Karangazi","Katabagemu","Kiyombe","Matimba","Mimuri","Mukama","Musheri","Nyagatare","Rukomo","Rwempasha","Rwimiyaga","Tabagwe"],"Rwamagana":["Fumbwe","Gahengeri","Gishali","Karenge","Kigabiro","Muhazi","Munyaga","Munyiginya","Musha","Muyumbu","Mwulire","Nyakaliro","Nzige","Rubona"],"Gasabo":["Bumbogo","Gatsata","Gikomero","Gisozi","Jabana","Jali","Kacyiru","Kimihurura","Kimironko","Kinyinya","Ndera","Nduba","Remera","Rusororo","Rutunga"],"Kicukiro":["Gahanga","Gatenga","Gikondo","Kagarama","Kanombe","Kicukiro","Kigarama","Masaka","Niboye","Nyarugunga"],"Nyarugenge":["Gitega","Kanyinya","Kigali","Kimisagara","Mageregere","Muhima","Nyakabanda","Nyamirambo","Nyarugenge","Rwezamenyo"],"Burera":["Bungwe","Butaro","Cyanika","Cyeru","Gahunga","Gatebe","Gitovu","Kagogo","Kinoni","Kinyababa","Kivuye","Nemba","Rugarama","Rugengabari","Ruhunde","Rusarabuye","Rwerere"],"Gakenke":["Busengo","Coko","Cyabingo","Gakenke","Gashenyi","Janja","Kamubuga","Karambo","Kivuruga","Mataba","Minazi","Mugunga","Muhondo","Muyongwe","Muzo","Nemba","Ruli","Rusasa","Rushashi"],"Gicumbi":["Bukure","Bwisige","Byumba","Cyumba","Giti","Kageyo","Kaniga","Manyagiro","Miyove","Mukarange","Muko","Mutete","Nyamiyaga","Nyankenke","Rubaya","Rukomo","Rushaki","Rutare","Ruvune","Rwamiko","Shangasha"],"Musanze":["Busogo","Cyuve","Gacaca","Gashaki","Gataraga","Kimonyi","Kinigi","Muhoza","Muko","Musanze","Nkotsi","Nyange","Remera","Rwaza","Shingiro"],"Rulindo":["Base","Burega","Bushoki","Buyoga","Cyinzuzi","Cyungo","Kinihira","Kisaro","Masoro","Mbogo","Murambi","Ngoma","Ntarabana","Rukozo","Rusiga","Shyorongi","Tumba"],"Gisagara":["Gikonko","Gishubi","Kansi","Kibirizi","Kigembe","Mamba","Muganza","Mugombwa","Mukindo","Musha","Ndora","Nyanza","Save"],"Huye":["Gishamvu","Huye","Karama","Kigoma","Kinazi","Maraba","Mbazi","Mukura","Ngoma","Ruhashya","Rusatira","Rwaniro","Simbi","Tumba"],"Kamonyi":["Gacurabwenge","Karama","Kayenzi","Kayumbu","Mugina","Musambira","Ngamba","Nyamiyaga","Nyarubaka","Rugarika","Rukoma","Runda"],"Muhanga":["Cyeza","Kabacuzi","Kibangu","Kiyumba","Muhanga","Mushishiro","Nyabinoni","Nyamabuye","Nyarusange","Rongi","Rugendabari","Shyogwe"],"Nyamagabe":["Buruhukiro","Cyanika","Gasaka","Gatare","Kaduha","Kamegeri","Kibirizi","Kibumbwe","Kitabi","Mbazi","Mugano","Musange","Musebeya","Mushubi","Nkomane","Tare","Uwinkingi"],"Nyanza":["Busasamana","Busoro","Cyabakamyi","Kibilizi","Kigoma","Mukingo","Muyira","Ntyazo","Nyagisozi","Rwabicuma"],"Nyaruguru":["Busanze","Cyahinda","Kibeho","Kivu","Mata","Muganza","Munini","Ngera","Ngoma","Nyabimata","Nyagisozi","Ruheru","Ruramba","Rusenge"],"Ruhango":["Bweramana","Byimana","Kabagali","Kinazi","Kinihira","Mbuye","Mwendo","Ntongwe","Ruhango"],"Karongi":["Bwishyura","Gashari","Gishyita","Gitesi","Mubuga","Murambi","Murundi","Mutuntu","Rubengera","Rugabano","Ruganda","Rwankuba","Twumba"],"Ngororero":["Bwira","Gatumba","Hindiro","Kabaya","Kageyo","Kavumu","Matyazo","Muhanda","Muhororo","Ndaro","Ngororero","Nyange","Sovu"],"Nyabihu":["Bigogwe","Jenda","Jomba","Kabatwa","Karago","Kintobo","Mukamira","Muringa","Rambura","Rugera","Rurembo","Shyira"],"Nyamasheke":["Bushekeri","Bushenge","Cyato","Gihombo","Kagano","Kanjongo","Karambi","Karengera","Kirimbi","Macuba","Mahembe","Nyabitekeri","Rangiro","Ruharambuga","Shangi"],"Rubavu":["Bugeshi","Busasamana","Cyanzarwe","Gisenyi","Kanama","Kanzenze","Mudende","Nyakiriba","Nyamyumba","Nyundo","Rubavu","Rugerero"],"Rusizi":["Bugarama","Butare","Bweyeye","Gashonga","Giheke","Gihundwe","Gikundamvura","Gitambi","Kamembe","Muganza","Mururu","Nkanka","Nkombo","Nkungu","Nyakabuye","Nyakarenzo","Nzahaha","Rwimbogo"],"Rutsiro":["Boneza","Gihango","Kigeyo","Kivumu","Manihira","Mukura","Murunda","Musasa","Mushonyi","Mushubati","Nyabirasi","Ruhango","Rusebeya"]};
const districts=Object.keys(districtSectors).sort();
const sectorsFor=district=>districtSectors[district]||[];
const roles={teacher:"Umwarimu ushaka permutation",job_seeker:"Umwarimu ushaka akazi",school:"Ikigo cy'amashuri",admin:"Administrator"};
function App(){const[session,setSession]=useState(null),[profile,setProfile]=useState(null),[loading,setLoading]=useState(true),[msg,setMsg]=useState(""),[err,setErr]=useState("");const[authOpen,setAuthOpen]=useState(false),[mode,setMode]=useState("login"),[requestOpen,setRequestOpen]=useState(false),[recoveryOpen,setRecoveryOpen]=useState(false),[newPassword,setNewPassword]=useState(""),[reportOpen,setReportOpen]=useState(false),[reportForm,setReportForm]=useState({target_type:"account",target_id:"",reason:""}),[legalPage,setLegalPage]=useState(null);const[auth,setAuth]=useState({full_name:"",email:"",password:"",role:"teacher"});const[requests,setRequests]=useState([]),[matches,setMatches]=useState([]),[jobs,setJobs]=useState([]),[applications,setApplications]=useState([]),[jobOpen,setJobOpen]=useState(false),[chatMatch,setChatMatch]=useState(null),[messages,setMessages]=useState([]),[messageBody,setMessageBody]=useState("");const[request,setRequest]=useState({current_school:"",current_district:"",current_sector:"",wanted_district:"",wanted_sector:"",wanted_sectors:[],subject:"",teaching_level:"",details:""});
useEffect(()=>{supabase.auth.getSession().then(({data})=>{setSession(data.session||null);setLoading(false)});const{data:{subscription}}=supabase.auth.onAuthStateChange((event,s)=>{setSession(s||null);if(event==="PASSWORD_RECOVERY")setRecoveryOpen(true)});return()=>subscription.unsubscribe()},[]);
useEffect(()=>{if(!session?.user){setProfile(null);return}loadAll(session.user.id)},[session]);
useEffect(()=>{if(session?.user)loadJobs(session.user.id)},[session,profile?.role]);
async function loadJobs(id){const{data:j,error:je}=await supabase.from("job_vacancies").select("*,schools(name)").eq("status","published").order("created_at",{ascending:false});if(je)setErr(je.message);else setJobs(j||[]);const{data:a,error:ae}=await supabase.from("job_applications").select("*,job_vacancies(title,subject,district,status)").eq("applicant_id",id).order("created_at",{ascending:false});if(!ae)setApplications(a||[])}
async function loadAll(id){
 setErr("");
 const[{data:p,error:pe},{data:r,error:re},{data:m,error:me}]=await Promise.all([
  supabase.from("profiles").select("*").eq("id",id).single(),
  supabase.from("permutation_requests").select("*").eq("teacher_id",id).order("created_at",{ascending:false}),
  supabase.from("permutation_matches").select("*").or(`teacher_a.eq.${id},teacher_b.eq.${id}`).order("created_at",{ascending:false})
 ]);
 if(pe)setErr(pe.message);else{setProfile(p);setRequest(x=>({...x,current_school:p.school_name||"",current_district:p.district||"",current_sector:p.sector||"",subject:p.subject||"",teaching_level:p.teaching_level||""}))}
 if(re)setErr(re.message);else setRequests(r||[]);
 if(me)setErr(me.message);else{
  const enriched=await Promise.all((m||[]).map(async match=>{
   const otherId=match.teacher_a===id?match.teacher_b:match.teacher_a;
   const{data:other}=await supabase.from("profiles").select("id,full_name,phone,district,school_name,subject,teaching_level").eq("id",otherId).single();
   return{...match,other};
  }));
  setMatches(enriched);
 }
}
async function requestPasswordReset(){
 if(!auth.email.trim()){setErr("Banza wandike email yawe.");return}
 const{error}=await supabase.auth.resetPasswordForEmail(auth.email.trim(),{redirectTo:window.location.origin});
 if(error)setErr(error.message);else{setMsg("Link yo guhindura password yoherejwe kuri email yawe.");setAuthOpen(false)}
}
async function updateRecoveredPassword(e){
 e.preventDefault();
 if(newPassword.length<8){setErr("Password igomba kugira nibura inyuguti 8.");return}
 const{error}=await supabase.auth.updateUser({password:newPassword});
 if(error)setErr(error.message);else{setMsg("Password yahinduwe neza.");setRecoveryOpen(false);setNewPassword("")}
}
async function submitAuth(e){e.preventDefault();setLoading(true);setErr("");try{if(mode==="register"){const{data,error}=await supabase.auth.signUp({email:auth.email.trim(),password:auth.password,options:{emailRedirectTo:window.location.origin,data:{full_name:auth.full_name.trim(),role:auth.role}}});if(error)throw error;setMsg(data.session?"Konti yakozwe.":"Reba email yawe wemeze konti.")}else{const{error}=await supabase.auth.signInWithPassword({email:auth.email.trim(),password:auth.password});if(error)throw error;setAuthOpen(false);setMsg("Winjiye muri konti neza.")}}catch(e){setErr(e.message)}finally{setLoading(false)}}
async function submitRequest(e){e.preventDefault();setLoading(true);setErr("");try{if(profile?.verification_status!=="verified")throw new Error("Konti yawe igomba kubanza kwemezwa na Admin.");if(!request.wanted_sectors?.length)throw new Error("Hitamo nibura Umurenge umwe ushaka kujyamo.");if(request.wanted_sectors.length>4)throw new Error("Ntushobora guhitamo imirenge irenze 4.");if(request.current_district===request.wanted_district&&request.wanted_sectors.includes(request.current_sector)&&request.wanted_sectors.length===1)throw new Error("Aho ukorera ntihashobora kuba ari ho honyine ushaka kujya.");const payload={...request,wanted_sector:request.wanted_sectors[0]||null,teacher_id:session.user.id,status:"active",published:true};const{error}=await supabase.from("permutation_requests").insert(payload);if(error)throw error;setRequestOpen(false);setMsg("Icyifuzo cya permutation cyabitswe.");await loadAll(session.user.id)}catch(e){setErr(e.message.includes("one_active")?"Usanzwe ufite icyifuzo cya permutation gifunguye.":e.message)}finally{setLoading(false)}}
async function setRequestStatus(id,status){const{error}=await supabase.from("permutation_requests").update({status,published:status==="active"}).eq("id",id);if(error)setErr(error.message);else{setMsg(status==="closed"?"Icyifuzo cyafunzwe.":"Icyifuzo cyasubijwe ku rubuga.");loadAll(session.user.id)}}
async function acceptMatch(matchId){
 setLoading(true);setErr("");
 const{error}=await supabase.rpc("accept_permutation_match",{p_match_id:matchId});
 if(error)setErr(error.message);else{setMsg("Match wayemeye. Dutegereje ko n'undi mwarimu ayemeza.");await loadAll(session.user.id)}
 setLoading(false);
}
async function openChat(match){
 setChatMatch(match);setMessageBody("");
 const otherId=match.teacher_a===session.user.id?match.teacher_b:match.teacher_a;
 const{data,error}=await supabase.from("messages").select("*").or(`and(sender_id.eq.${session.user.id},receiver_id.eq.${otherId}),and(sender_id.eq.${otherId},receiver_id.eq.${session.user.id})`).order("created_at",{ascending:true});
 if(error)setErr(error.message);else setMessages(data||[]);
}
async function sendMessage(e){
 e.preventDefault();if(!messageBody.trim()||!chatMatch)return;
 const otherId=chatMatch.teacher_a===session.user.id?chatMatch.teacher_b:chatMatch.teacher_a;
 const{error}=await supabase.from("messages").insert({sender_id:session.user.id,receiver_id:otherId,body:messageBody.trim()});
 if(error)setErr(error.message);else{setMessageBody("");await openChat(chatMatch)}
}
async function completePermutation(matchId){
 if(!window.confirm("Wemeza ko wabonye permutation? Ibi bizafunga ibyifuzo byanyu."))return;
 const{error}=await supabase.rpc("complete_permutation_match",{p_match_id:matchId});
 if(error)setErr(error.message);else{setMsg("Permutation yanditswe ko yabonetse kandi ibyifuzo byafunzwe.");setChatMatch(null);await loadAll(session.user.id)}
}
async function applyJob(job){
 const cover=window.prompt("Andika ubutumwa bugufi bwo gusaba aka kazi:")||"";
 const{error}=await supabase.from("job_applications").insert({vacancy_id:job.id,applicant_id:session.user.id,cover_letter:cover,status:"new"});
 if(error)setErr(error.message);else{setMsg("Application yoherejwe neza.");loadJobs(session.user.id)}
}
async function submitReport(e){
 e.preventDefault();setErr("");
 const targetId=reportForm.target_id.trim()||null;
 const{error}=await supabase.from("reports").insert({reporter_id:session.user.id,target_type:reportForm.target_type,target_id:targetId,reason:reportForm.reason.trim(),status:"pending"});
 if(error)setErr(error.message);else{setMsg("Report yakiriwe. Admin azayisuzuma.");setReportOpen(false);setReportForm({target_type:"account",target_id:"",reason:""})}
}
async function logout(){await supabase.auth.signOut()}
if(loading&&!session)return <div className="loading">Mwarimu Connect irimo gufunguka...</div>;
return <div><header><div className="brand"><span>↔</span>Mwarimu Connect</div><nav><a href="#home">Ahabanza</a><a href="#permutation">Permutation</a></nav>{session?<div className="headerActions"><button className="reportBtn" onClick={()=>setReportOpen(true)}>Tanga report</button><button className="outline" onClick={logout}>Sohoka</button></div>:<button className="primary" onClick={()=>setAuthOpen(true)}>Injira</button>}</header>{msg&&<div className="notice ok">✓ {msg}</div>}{err&&<div className="notice bad">⚠ {err}</div>}{!session?<Home register={()=>{setMode("register");setAuthOpen(true)}}/>:profile?.is_suspended?<SuspendedAccount profile={profile}/>:profile?.role==="admin"?<Admin/>:profile?.role==="job_seeker"?<JobSeeker profile={profile} jobs={jobs} applications={applications} applyJob={applyJob}/>:profile?.role==="school"?<SchoolDashboard profile={profile}/>:<Dashboard profile={profile} requests={requests} matches={matches} userId={session.user.id} openRequest={()=>setRequestOpen(true)} setStatus={setRequestStatus} acceptMatch={acceptMatch} openChat={openChat} completePermutation={completePermutation}/>}<footer><p>© 2026 Mwarimu Connect</p><div className="footerLinks"><button onClick={()=>setLegalPage("privacy")}>Privacy Policy</button><button onClick={()=>setLegalPage("terms")}>Terms of Use</button><button onClick={()=>setLegalPage("safety")}>Safety Guidelines</button></div></footer>{authOpen&&<Auth auth={auth} setAuth={setAuth} mode={mode} setMode={setMode} submit={submitAuth} reset={requestPasswordReset} close={()=>setAuthOpen(false)} loading={loading}/>} {requestOpen&&<RequestModal value={request} setValue={setRequest} submit={submitRequest} close={()=>setRequestOpen(false)} loading={loading}/>} {chatMatch&&<ChatModal match={chatMatch} userId={session.user.id} messages={messages} body={messageBody} setBody={setMessageBody} send={sendMessage} close={()=>setChatMatch(null)} complete={()=>completePermutation(chatMatch.id)}/>} {recoveryOpen&&<div className="overlay"><form className="modal" onSubmit={updateRecoveredPassword}><h2>Shyiraho password nshya</h2><label>Password nshya<input type="password" minLength="8" value={newPassword} onChange={e=>setNewPassword(e.target.value)} required/></label><button className="primary full">Hindura password</button></form></div>} {reportOpen&&<ReportModal value={reportForm} setValue={setReportForm} submit={submitReport} close={()=>setReportOpen(false)}/>} {legalPage&&<LegalModal page={legalPage} close={()=>setLegalPage(null)}/>}</div>}
function Home({register}){return <main><section className="hero" id="home"><div><small>Urubuga rw'abarimu bo mu Rwanda</small><h1>Permutation, akazi n'amahirwe y'abarimu hamwe.</h1><p>Shaka uwo mwahuza permutation mu buryo bwizewe.</p><button className="primary" onClick={register}>Fungura konti →</button></div><div className="art">👩🏾‍🏫 <b>↔</b> 👨🏾‍🏫</div></section></main>}
function Dashboard({profile,requests,matches,userId,openRequest,setStatus,acceptMatch,openChat,completePermutation}){
 const current=requests.find(x=>["active","matched","submitted","approved"].includes(x.status));
 return <main className="dashboard" id="permutation">
  <section className="welcome"><div><small>Murakaza neza</small><h1>{profile?.full_name}</h1><p>{roles[profile?.role]}</p></div><span className={`badge ${profile?.verification_status==="verified"?"verified":"pending"}`}>{profile?.verification_status==="verified"?"✓ Konti yemejwe":"Iri gutegereza kwemezwa"}</span></section>
  <section className="metrics"><article><b>{requests.length}</b><span>Ibyifuzo</span></article><article><b>{matches.length}</b><span>Matches</span></article><article><b>0</b><span>Ubutumwa</span></article></section>
  <section className="toolbar"><h2>Permutation yanjye</h2><button className="primary" disabled={profile?.verification_status!=="verified"||!!current} onClick={openRequest}>+ Tanga icyifuzo</button></section>
  {profile?.verification_status!=="verified"&&<div className="warning">Konti igomba kubanza kwemezwa kugira ngo utange icyifuzo.</div>}
  <section className="list">{requests.length?requests.map(r=><article key={r.id}><div className="route"><div><small>Arava</small><b>{r.current_district}</b><span>{r.current_sector||"Umurenge nturatangwa"} · {r.current_school}</span></div><strong>→</strong><div><small>Ashaka kujya</small><b>{r.wanted_district}</b><span>{(r.wanted_sectors?.length?r.wanted_sectors:[r.wanted_sector]).filter(Boolean).join(", ")||"Imirenge ntiratangwa"} · {r.subject} · {r.teaching_level}</span></div></div><div className="row"><span className="badge pending">{r.status}</span>{r.status==="active"?<button className="reject" onClick={()=>setStatus(r.id,"closed")}>Funga icyifuzo</button>:<button className="outline" onClick={()=>setStatus(r.id,"active")}>Subiza ku rubuga</button>}</div></article>):<div className="empty">Nta cyifuzo cya permutation uratanga.</div>}</section>
  <h2>Matches zabonetse</h2>
  <section className="list">{matches.length?matches.map(m=>{
   const mine=m.teacher_a===userId?m.teacher_a_accepted:m.teacher_b_accepted;
   const otherAccepted=m.teacher_a===userId?m.teacher_b_accepted:m.teacher_a_accepted;
   const both=mine===true&&otherAccepted===true;
   return <article key={m.id} className="matchCard"><div className="row"><div><h3>{m.other?.full_name||"Umwarimu wahujwe nawe"}</h3><p>{m.other?.district||""} · {m.other?.school_name||""}</p></div><span className={`badge ${both?"verified":"pending"}`}>{both?"Bombi bemeye":mine?"Wowe waremeje":"Match nshya"}</span></div><div className="adminGrid"><p><b>Isomo:</b> {m.other?.subject||"-"}</p><p><b>Urwego:</b> {m.other?.teaching_level||"-"}</p><p><b>Wowe:</b> {mine?"Wemeje":"Nturayemeza"}</p><p><b>Undi:</b> {otherAccepted?"Yemeje":"Aracyategerejwe"}</p></div>{both?<div className="contactBox"><b>Telefone:</b> {m.other?.phone||"Nta telefone yashyizweho"}<p>Ubu mwembi mwemeye. Mushobora kuvugana mugakomeza inzira ya permutation.</p><div className="matchActions"><button className="primary" onClick={()=>openChat(m)}>Andika ubutumwa</button><button className="approve" onClick={()=>completePermutation(m.id)}>Nabonye permutation</button></div></div>:<button className="approve" disabled={mine===true} onClick={()=>acceptMatch(m.id)}>{mine?"✓ Match wayemeye":"Ndemera iyi match"}</button>}</article>
  }):<div className="empty">Nta match iraboneka. System izakumenyesha igihe habonetse icyifuzo gihuye n'icyawe.</div>}</section>
 </main>
}
function Admin(){
 const[verifications,setVerifications]=useState([]),[permutations,setPermutations]=useState([]),[schools,setSchools]=useState([]),[busy,setBusy]=useState(true),[error,setError]=useState("");
 useEffect(()=>{loadAdmin()},[]);
 async function loadAdmin(){
  setBusy(true);setError("");
  const[{data:v,error:ve},{data:p,error:pe},{data:s,error:se}]=await Promise.all([
   supabase.from("teacher_verifications").select("id,teacher_id,registration_number,document_path,status,admin_note,created_at,profiles!teacher_id(full_name,email,phone,district,school_name,subject,teaching_level)").order("created_at",{ascending:false}),
   supabase.from("permutation_requests").select("*,profiles!teacher_id(full_name,email,phone,verification_status)").order("created_at",{ascending:false}),
   supabase.from("schools").select("*").order("created_at",{ascending:false})
  ]);
  if(ve)setError(ve.message);else setVerifications(v||[]);
  if(pe)setError(x=>x||pe.message);else setPermutations(p||[]);
  if(se)setError(x=>x||se.message);else setSchools(s||[]);
  setBusy(false);
 }
 async function review(item,status){
  const note=status==="rejected"?(window.prompt("Andika impamvu yo kwanga cyangwa ibyo agomba gukosora:")||""):"Konti yagenzuwe kandi yemejwe.";
  const{error}=await supabase.rpc("review_teacher_verification",{p_teacher_id:item.teacher_id,p_status:status,p_note:note});
  if(error)setError(error.message);else loadAdmin();
 }
 async function openDocument(path){
  const{data,error}=await supabase.storage.from("verification-documents").createSignedUrl(path,120);
  if(error)setError(error.message);else window.open(data.signedUrl,"_blank");
 }
 async function reviewSchool(id,status){const note=status==="rejected"?(window.prompt("Andika impamvu yo kwanga ikigo:")||""):"Ikigo cyagenzuwe kandi cyemejwe.";const{error}=await supabase.rpc("review_school_verification",{p_school_id:id,p_status:status,p_note:note});if(error)setError(error.message);else loadAdmin()}
 async function openSchoolDocument(path){const{data,error}=await supabase.storage.from("verification-documents").createSignedUrl(path,120);if(error)setError(error.message);else window.open(data.signedUrl,"_blank")}
 return <main className="dashboard">
  <section className="welcome"><div><small>Admin Dashboard</small><h1>Gucunga Mwarimu Connect</h1><p>{verifications.filter(x=>x.status==="pending").length} bategereje kwemezwa · {permutations.filter(x=>x.status==="active").length} permutation zikora</p></div><button className="outline" onClick={loadAdmin}>Vugurura</button></section>
  {error&&<div className="warning">{error}</div>}
  <h2>Abategereje kwemezwa</h2>
  <section className="list">{busy?<p>Birimo gufunguka...</p>:verifications.length?verifications.map(item=><article key={item.id}><div className="row"><div><h3>{item.profiles?.full_name||"Nta zina"}</h3><p>{item.profiles?.email}</p></div><span className={`badge ${item.status==="verified"?"verified":"pending"}`}>{item.status}</span></div><div className="adminGrid"><p><b>Telefone:</b> {item.profiles?.phone||"-"}</p><p><b>Akarere:</b> {item.profiles?.district||"-"}</p><p><b>Ikigo:</b> {item.profiles?.school_name||"-"}</p><p><b>Isomo:</b> {item.profiles?.subject||"-"}</p><p><b>Urwego:</b> {item.profiles?.teaching_level||"-"}</p><p><b>Registration No:</b> {item.registration_number||"-"}</p></div><div className="adminButtons">{item.document_path&&<button className="outline" onClick={()=>openDocument(item.document_path)}>Reba icyemezo</button>}<button className="approve" onClick={()=>review(item,"verified")}>✓ Emeza</button><button className="reject" onClick={()=>review(item,"rejected")}>✕ Anga</button></div></article>):<div className="empty">Nta cyifuzo cyo kwemezwa kirahari.</div>}</section>
  <h2>Ibigo bitegereje kwemezwa</h2>
  <section className="list">{schools.length?schools.map(s=><article key={s.id}><div className="row"><div><h3>{s.name}</h3><p>{s.email} · {s.phone||"Nta telefone"}</p></div><span className={`badge ${s.verification_status==="verified"?"verified":"pending"}`}>{s.verification_status||"pending"}</span></div><div className="adminGrid"><p><b>Akarere:</b> {s.district}</p><p><b>Umurenge:</b> {s.sector||"-"}</p><p><b>Registration:</b> {s.registration_number||"-"}</p><p><b>Uhagarariye:</b> {s.representative_name||"-"}</p></div><div className="applicationActions">{s.document_path&&<button className="outline" onClick={()=>openSchoolDocument(s.document_path)}>Reba icyemezo</button>}<button className="approve" onClick={()=>reviewSchool(s.id,"verified")}>✓ Emeza ikigo</button><button className="reject" onClick={()=>reviewSchool(s.id,"rejected")}>✕ Anga ikigo</button></div></article>):<div className="empty">Nta kigo kirategereza kwemezwa.</div>}</section>
  <h2>Ibyifuzo bya permutation</h2>
  <section className="list">{permutations.length?permutations.map(r=><article key={r.id}><div className="row"><div><h3>{r.profiles?.full_name||"Umwarimu"}</h3><p>{r.profiles?.email} · {r.profiles?.phone||"Nta telefone"}</p></div><span className="badge pending">{r.status}</span></div><div className="route"><div><small>Arava</small><b>{r.current_district}</b><span>{r.current_sector||"Umurenge nturatangwa"} · {r.current_school}</span></div><strong>→</strong><div><small>Ashaka kujya</small><b>{r.wanted_district}</b><span>{(r.wanted_sectors?.length?r.wanted_sectors:[r.wanted_sector]).filter(Boolean).join(", ")||"Imirenge ntiratangwa"} · {r.subject} · {r.teaching_level}</span></div></div>{r.details&&<p><b>Ibisobanuro:</b> {r.details}</p>}</article>):<div className="empty">Nta cyifuzo cya permutation kiratangwa.</div>}</section>
  <AdminModeration/>
 </main>
}
function LegalModal({page,close}){
 const content={
  privacy:{title:"Privacy Policy",body:<><p><b>Last updated: 4 November 2026</b></p><p>Mwarimu Connect collects only information needed to provide teacher verification, permutation matching, recruitment, messaging, security and support services.</p><h3>Information collected</h3><ul><li>Names, email, telephone, district, school, subject and teaching level.</li><li>Teacher or school verification documents.</li><li>CV, qualifications, experience and job applications.</li><li>Permutation requests, matches, messages, reports and account activity.</li></ul><h3>How information is used</h3><ul><li>To create and secure accounts.</li><li>To verify teachers and schools.</li><li>To match permutation requests.</li><li>To connect job seekers with verified schools.</li><li>To prevent fraud, investigate reports and protect users.</li></ul><h3>Sharing</h3><p>Personal information is shown only where needed for a service. Telephone numbers for permutation are revealed after both matched teachers accept. CVs and applications are available only to the applicant, authorized school and Admin.</p><h3>Storage and security</h3><p>Account and service data are stored using Supabase and the website is hosted using Vercel. Access restrictions and row-level security are used to reduce unauthorized access.</p><h3>Your rights</h3><p>Users may request access, correction, restriction or deletion of personal information, subject to legal and security requirements. Users may also object to certain processing or file a complaint with Rwanda's Data Protection and Privacy Office.</p><h3>Contact</h3><p>Before public launch, Mwarimu Connect must add an official support email, telephone number and physical/business contact details here.</p></>},
  terms:{title:"Terms of Use",body:<><p><b>Last updated: 4 November 2026</b></p><p>By creating an account or using Mwarimu Connect, the user agrees to these terms.</p><h3>Account responsibilities</h3><ul><li>Provide truthful and current information.</li><li>Keep login details confidential.</li><li>Do not create false teacher, school or vacancy records.</li><li>Do not impersonate another person or institution.</li></ul><h3>Verification</h3><p>Verification confirms that submitted information was reviewed. Verification does not guarantee employment, transfer approval, professional performance or conduct.</p><h3>Permutation</h3><p>Mwarimu Connect helps users identify possible matches. A match is not an official transfer. Users remain responsible for following employer and government procedures before changing workplaces.</p><h3>Recruitment</h3><p>Mwarimu Connect does not guarantee that a user will obtain employment or that a school will hire a particular applicant. Schools are responsible for lawful recruitment and accurate vacancy information.</p><h3>Prohibited conduct</h3><ul><li>Fraud, harassment, threats or unlawful content.</li><li>Collecting or publishing another user's private information without permission.</li><li>Uploading malicious files or attempting unauthorized access.</li><li>Using the service to demand unofficial payments for employment or permutation.</li></ul><h3>Moderation</h3><p>Mwarimu Connect may investigate reports, suspend accounts, remove false vacancies, close abusive requests and preserve records required for security or legal compliance.</p><h3>Service availability</h3><p>The service may be changed, interrupted or temporarily unavailable for maintenance, security or technical reasons.</p></>},
  safety:{title:"Safety Guidelines",body:<><h3>Protect personal information</h3><ul><li>Do not publish passwords, national ID numbers, bank information or private documents in messages.</li><li>Use telephone details only for the agreed permutation or recruitment purpose.</li></ul><h3>Avoid fraud</h3><ul><li>Do not pay an individual who promises guaranteed employment or permutation.</li><li>Verify interview invitations and school identity.</li><li>Use the Tanga report button when information appears false or unsafe.</li></ul><h3>Official procedures</h3><p>Permutation and recruitment must follow applicable official procedures. A website match, message or selected status is not a government authorization or employment contract.</p><h3>Emergency or criminal matters</h3><p>Contact the appropriate authorities where there is immediate danger, fraud, threats or criminal conduct. Website reporting does not replace an official police or regulatory complaint.</p></>}
 };
 const selected=content[page];
 return <div className="overlay"><div className="modal legalModal"><button className="close" onClick={close}>✕</button><h2>{selected.title}</h2><div className="legalContent">{selected.body}</div><button className="primary full" onClick={close}>Funga</button></div></div>
}
function SuspendedAccount({profile}){return <main className="dashboard"><div className="suspendedCard"><h1>Konti yahagaritswe</h1><p>{profile?.suspension_reason||"Konti yahagaritswe na Admin mu gihe hakorwa igenzura."}</p><p>Niba ubona ari amakosa, koresha Tanga report cyangwa uvugane na Admin.</p></div></main>}
function ReportModal({value,setValue,submit,close}){const c=e=>setValue({...value,[e.target.name]:e.target.value});return <div className="overlay"><form className="modal" onSubmit={submit}><button type="button" className="close" onClick={close}>✕</button><h2>Tanga report</h2><label>Ubwoko<select name="target_type" value={value.target_type} onChange={c}><option value="account">Konti</option><option value="permutation">Permutation</option><option value="vacancy">Vacancy</option><option value="message">Ubutumwa</option><option value="school">Ikigo</option></select></label><label>ID y'icyo utangaho report, niba uyizi<input name="target_id" value={value.target_id} onChange={c} placeholder="UUID cyangwa usige blank"/></label><label>Impamvu<textarea name="reason" value={value.reason} onChange={c} minLength="10" required/></label><button className="primary full">Ohereza report</button></form></div>}
function AdminModeration(){
 const[reports,setReports]=useState([]),[users,setUsers]=useState([]),[vacancies,setVacancies]=useState([]),[stats,setStats]=useState({}),[error,setError]=useState("");
 useEffect(()=>{load()},[]);
 async function load(){
  setError("");
  const[{data:r,error:re},{data:u,error:ue},{data:v,error:ve},{count:pc},{count:sc},{count:mc},{count:ac}]=await Promise.all([
   supabase.from("reports").select("*").order("created_at",{ascending:false}),
   supabase.from("profiles").select("id,full_name,email,role,verification_status,is_suspended,suspension_reason,created_at").order("created_at",{ascending:false}),
   supabase.from("job_vacancies").select("id,title,subject,district,status,created_at").order("created_at",{ascending:false}),
   supabase.from("profiles").select("id",{count:"exact",head:true}),
   supabase.from("schools").select("id",{count:"exact",head:true}),
   supabase.from("permutation_matches").select("id",{count:"exact",head:true}),
   supabase.from("job_applications").select("id",{count:"exact",head:true})
  ]);
  if(re||ue||ve)setError(re?.message||ue?.message||ve?.message||"");
  setReports(r||[]);setUsers(u||[]);setVacancies(v||[]);setStats({profiles:pc||0,schools:sc||0,matches:mc||0,applications:ac||0});
 }
 async function suspend(user,suspend){const reason=suspend?(window.prompt("Andika impamvu yo guhagarika konti:")||""):null;if(suspend&&!reason)return;const{error}=await supabase.rpc("set_account_suspension",{p_user_id:user.id,p_suspend:suspend,p_reason:reason});if(error)setError(error.message);else load()}
 async function reviewReport(report,status){const note=window.prompt("Andika Admin note:")||"";const{error}=await supabase.rpc("review_report",{p_report_id:report.id,p_status:status,p_admin_note:note});if(error)setError(error.message);else load()}
 async function closeVacancy(id){const reason=window.prompt("Impamvu yo gufunga vacancy:")||"Admin moderation";const{error}=await supabase.rpc("admin_close_vacancy",{p_vacancy_id:id,p_reason:reason});if(error)setError(error.message);else load()}
 async function suspendPermutation(id){const reason=window.prompt("Impamvu yo guhagarika permutation:")||"Admin moderation";const{error}=await supabase.rpc("admin_suspend_permutation",{p_request_id:id,p_reason:reason});if(error)setError(error.message);else load()}
 return <section className="moderation"><div className="toolbar"><h2>Admin Moderation</h2><button className="outline" onClick={load}>Vugurura</button></div>{error&&<div className="warning">{error}</div>}<section className="metrics"><article><b>{stats.profiles}</b><span>Abakoresha</span></article><article><b>{stats.schools}</b><span>Ibigo</span></article><article><b>{stats.matches}</b><span>Matches</span></article><article><b>{stats.applications}</b><span>Applications</span></article></section><h2>Reports</h2><section className="list">{reports.length?reports.map(r=><article key={r.id} className="reportCard"><div className="row"><div><h3>{r.target_type}</h3><p>{r.reason}</p></div><span className="badge pending">{r.status}</span></div><p><b>Target ID:</b> {r.target_id||"Nta ID yatanzwe"}</p><div className="adminButtons"><button className="interview" onClick={()=>reviewReport(r,"investigating")}>Investigating</button><button className="approve" onClick={()=>reviewReport(r,"resolved")}>Resolved</button><button className="outline" onClick={()=>reviewReport(r,"dismissed")}>Dismissed</button>{r.target_type==="vacancy"&&r.target_id&&<button className="reject" onClick={()=>closeVacancy(r.target_id)}>Funga vacancy</button>}{r.target_type==="permutation"&&r.target_id&&<button className="reject" onClick={()=>suspendPermutation(r.target_id)}>Hagarika permutation</button>}</div></article>):<div className="empty">Nta report iratangwa.</div>}</section><h2>Konti z'abakoresha</h2><section className="list userList">{users.map(u=><article key={u.id}><div className="row"><div><h3>{u.full_name}</h3><p>{u.email} · {u.role}</p></div><span className={`badge ${u.is_suspended?"suspended":"verified"}`}>{u.is_suspended?"suspended":u.verification_status}</span></div><div className="adminButtons">{u.role!=="admin"&&(u.is_suspended?<button className="approve" onClick={()=>suspend(u,false)}>Subiza konti</button>:<button className="reject" onClick={()=>suspend(u,true)}>Hagarika konti</button>)}</div></article>)}</section><h2>Vacancies zose</h2><section className="list">{vacancies.map(v=><article key={v.id}><div className="row"><div><h3>{v.title}</h3><p>{v.subject} · {v.district}</p></div><span className="badge pending">{v.status}</span></div>{v.status!=="closed"&&<button className="reject" onClick={()=>closeVacancy(v.id)}>Funga vacancy</button>}</article>)}</section></section>
}
function Auth({auth,setAuth,mode,setMode,submit,reset,close,loading}){const c=e=>setAuth({...auth,[e.target.name]:e.target.value});return <div className="overlay"><form className="modal" onSubmit={submit}><button type="button" className="close" onClick={close}>✕</button><h2>{mode==="register"?"Fungura konti":"Injira"}</h2>{mode==="register"&&<><label>Amazina<input name="full_name" value={auth.full_name} onChange={c} required/></label><label>Konti<select name="role" value={auth.role} onChange={c}>{Object.entries(roles).filter(([x])=>x!=="admin").map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label></>}<label>Email<input name="email" type="email" value={auth.email} onChange={c} required/></label><label>Password<input name="password" type="password" minLength="8" value={auth.password} onChange={c} required/></label><button className="primary full" disabled={loading}>{loading?"Tegereza...":mode==="register"?"Kora konti":"Injira"}</button><button type="button" className="link" onClick={()=>setMode(mode==="register"?"login":"register")}>{mode==="register"?"Usanzwe ufite konti? Injira":"Nta konti ufite? Fungura konti"}</button>{mode==="login"&&<button type="button" className="link resetLink" onClick={reset}>Nibagiwe password</button>}</form></div>}
function RequestModal({value,setValue,submit,close,loading}){
 const c=e=>setValue({...value,[e.target.name]:e.target.value});
 const changeCurrentDistrict=e=>setValue({...value,current_district:e.target.value,current_sector:""});
 const changeWantedDistrict=e=>setValue({...value,wanted_district:e.target.value,wanted_sector:"",wanted_sectors:[]});
 return <div className="overlay"><form className="modal wide" onSubmit={submit}><button type="button" className="close" onClick={close}>✕</button><h2>Tanga icyifuzo cya permutation</h2><div className="formGrid"><label>Ikigo ukoreramo<input name="current_school" value={value.current_school} onChange={c} required/></label><label>Akarere ukoreramo<select name="current_district" value={value.current_district} onChange={changeCurrentDistrict} required><option value="">Hitamo Akarere</option>{districts.map(x=><option key={x} value={x}>{x}</option>)}</select></label><label>Umurenge ukoreramo<select name="current_sector" value={value.current_sector} onChange={c} disabled={!value.current_district} required><option value="">{value.current_district?"Hitamo Umurenge":"Banza uhitemo Akarere"}</option>{sectorsFor(value.current_district).map(x=><option key={x} value={x}>{x}</option>)}</select></label><label>Akarere ushaka kujyamo<select name="wanted_district" value={value.wanted_district} onChange={changeWantedDistrict} required><option value="">Hitamo Akarere</option>{districts.map(x=><option key={x} value={x}>{x}</option>)}</select></label><fieldset className="sectorPicker" disabled={!value.wanted_district}><legend>Imirenge ushaka kujyamo, hitamo kugeza kuri 4</legend><p className="sectorCount">Wahisemo {value.wanted_sectors?.length||0} / 4</p><div className="sectorOptions">{value.wanted_district?sectorsFor(value.wanted_district).map(x=>{const checked=(value.wanted_sectors||[]).includes(x);const disabled=!checked&&(value.wanted_sectors||[]).length>=4;return <label key={x} className={disabled?"sectorDisabled":""}><input type="checkbox" checked={checked} disabled={disabled} onChange={()=>{const current=value.wanted_sectors||[];const next=checked?current.filter(s=>s!==x):[...current,x];setValue({...value,wanted_sectors:next,wanted_sector:next[0]||""})}}/>{x}</label>}):<p>Banza uhitemo Akarere</p>}</div></fieldset><label>Isomo<input name="subject" value={value.subject} onChange={c} required/></label><label>Urwego<select name="teaching_level" value={value.teaching_level} onChange={c} required><option value="">Hitamo</option>{["Nursery","Primary","Secondary","TVET"].map(x=><option key={x}>{x}</option>)}</select></label><label>Ibisobanuro<textarea name="details" value={value.details} onChange={c}/></label></div><button className="primary full" disabled={loading}>{loading?"Birimo koherezwa...":"Ohereza icyifuzo"}</button></form></div>}
function JobSeeker({profile,jobs,applications,applyJob}){
 const[jobProfile,setJobProfile]=useState(null),[notifications,setNotifications]=useState([]),[open,setOpen]=useState(false),[saving,setSaving]=useState(false),[error,setError]=useState("");
 const[form,setForm]=useState({qualification:"",years_experience:0,preferred_districts:"",employment_type:"Full-time",available_from:""});
 const[cvFile,setCvFile]=useState(null);
 useEffect(()=>{loadExtra()},[]);
 async function loadExtra(){
  const[{data:j,error:je},{data:n,error:ne}]=await Promise.all([
   supabase.from("job_profiles").select("*").eq("user_id",profile.id).maybeSingle(),
   supabase.from("notifications").select("*").eq("user_id",profile.id).order("created_at",{ascending:false}).limit(20)
  ]);
  if(je)setError(je.message);else if(j){setJobProfile(j);setForm({qualification:j.qualification||"",years_experience:j.years_experience||0,preferred_districts:(j.preferred_districts||[]).join(", "),employment_type:j.employment_type||"Full-time",available_from:j.available_from||""})}
  if(ne)setError(ne.message);else setNotifications(n||[]);
 }
 async function saveProfile(e){
  e.preventDefault();setSaving(true);setError("");
  try{
   let cvPath=jobProfile?.cv_path||null;
   if(cvFile){
    cvPath=`${profile.id}/cv-${Date.now()}.pdf`;
    const{error:u}=await supabase.storage.from("cvs").upload(cvPath,cvFile,{upsert:false});
    if(u)throw u;
   }
   const payload={user_id:profile.id,qualification:form.qualification,years_experience:Number(form.years_experience)||0,preferred_districts:form.preferred_districts.split(",").map(x=>x.trim()).filter(Boolean),employment_type:form.employment_type,available_from:form.available_from||null,cv_path:cvPath,visible_to_schools:true};
   const{error}=await supabase.from("job_profiles").upsert(payload,{onConflict:"user_id"});
   if(error)throw error;
   setOpen(false);await loadExtra();
  }catch(e){setError(e.message)}finally{setSaving(false)}
 }
 async function markRead(id){await supabase.from("notifications").update({read_at:new Date().toISOString()}).eq("id",id);loadExtra()}
 const c=e=>setForm({...form,[e.target.name]:e.target.value});
 return <main className="dashboard">
  <section className="welcome"><div><small>Job Seeker Dashboard</small><h1>{profile?.full_name}</h1><p>Shaka akazi ko kwigisha</p></div><button className="primary" onClick={()=>setOpen(true)}>{jobProfile?"Hindura Job Profile":"Uzuza Job Profile"}</button></section>
  {error&&<div className="warning">{error}</div>}
  <section className="metrics"><article><b>{jobs.length}</b><span>Vacancies</span></article><article><b>{applications.length}</b><span>Applications</span></article><article><b>{notifications.filter(x=>!x.read_at).length}</b><span>Notifications nshya</span></article></section>
  <section className="dashboardGrid"><article><h2>Job Profile</h2><p><b>Impamyabumenyi:</b> {jobProfile?.qualification||"Ntuzuye"}</p><p><b>Uburambe:</b> {jobProfile?.years_experience??0} years</p><p><b>Uturere:</b> {(jobProfile?.preferred_districts||[]).join(", ")||"Ntuzuye"}</p><p><b>CV:</b> {jobProfile?.cv_path?"Yashyizweho":"Ntirashyirwaho"}</p></article><article><h2>Notifications</h2>{notifications.length?notifications.slice(0,5).map(n=><div className={`notification ${n.read_at?"read":"unread"}`} key={n.id} onClick={()=>markRead(n.id)}><b>{n.title}</b><p>{n.body}</p></div>):<p>Nta notification irahari.</p>}</article></section>
  <h2>Imyanya y'akazi ihari</h2><section className="list">{jobs.length?jobs.map(j=><article key={j.id}><div className="row"><div><h3>{j.title}</h3><p>{j.schools?.name||"Ikigo"} · {j.district}</p></div><span className="badge verified">{j.status}</span></div><div className="adminGrid"><p><b>Isomo:</b> {j.subject}</p><p><b>Urwego:</b> {j.teaching_level}</p><p><b>Uburambe:</b> {j.minimum_experience} years</p><p><b>Deadline:</b> {j.deadline}</p></div><p>{j.description}</p><button className="primary" disabled={!jobProfile?.cv_path||applications.some(a=>a.vacancy_id===j.id)} onClick={()=>applyJob(j)}>{!jobProfile?.cv_path?"Banza ushyireho CV":applications.some(a=>a.vacancy_id===j.id)?"Warasabye":"Saba akazi"}</button></article>):<div className="empty">Nta vacancy iratangazwa.</div>}</section>
  <h2>Applications zanjye</h2><section className="list">{applications.length?applications.map(a=><article key={a.id}><h3>{a.job_vacancies?.title}</h3><p>{a.job_vacancies?.subject} · {a.job_vacancies?.district}</p><span className="badge pending">{a.status}</span>{a.status==="interview"&&<div className="interviewBox"><p><b>Itariki n'isaha:</b> {a.interview_at?new Date(a.interview_at).toLocaleString():"Ntibirashyirwaho"}</p><p><b>Aho interview izabera:</b> {a.interview_location||"Ntiharatangazwa"}</p>{a.interview_note&&<p><b>Amabwiriza:</b> {a.interview_note}</p>}</div>}</article>):<div className="empty">Nta kazi urasaba.</div>}</section>
  {open&&<div className="overlay"><form className="modal wide" onSubmit={saveProfile}><button type="button" className="close" onClick={()=>setOpen(false)}>✕</button><h2>Job Profile na CV</h2><div className="formGrid"><label>Impamyabumenyi<input name="qualification" value={form.qualification} onChange={c} required/></label><label>Imyaka y'uburambe<input name="years_experience" type="number" min="0" value={form.years_experience} onChange={c} required/></label><label>Uturere ushaka gukoreramo<input name="preferred_districts" value={form.preferred_districts} onChange={c} placeholder="Gasabo, Kicukiro, Huye" required/></label><label>Ubwoko bw'akazi<select name="employment_type" value={form.employment_type} onChange={c}><option>Full-time</option><option>Part-time</option><option>Contract</option></select></label><label>Igihe watangirira<input name="available_from" type="date" value={form.available_from} onChange={c}/></label><label>CV ya PDF<input type="file" accept="application/pdf,.pdf" onChange={e=>setCvFile(e.target.files?.[0]||null)} required={!jobProfile?.cv_path}/></label></div><button className="primary full" disabled={saving}>{saving?"Birimo kubikwa...":"Bika Job Profile"}</button></form></div>}
 </main>
}
function SchoolDashboard({profile}){
 const[school,setSchool]=useState(null),[vacancies,setVacancies]=useState([]),[applications,setApplications]=useState([]),[open,setOpen]=useState(false),[profileOpen,setProfileOpen]=useState(false),[selectedVacancy,setSelectedVacancy]=useState("all"),[documentFile,setDocumentFile]=useState(null),[error,setError]=useState("");
 const[schoolForm,setSchoolForm]=useState({name:"",district:"",sector:"",phone:"",email:profile?.email||"",registration_number:"",representative_name:""});
 const[vacancyForm,setVacancyForm]=useState({title:"",subject:"",teaching_level:"Primary",district:"",qualification:"",minimum_experience:0,employment_type:"Full-time",description:"",deadline:""});
 useEffect(()=>{load()},[]);
 async function load(){setError("");const{data:s,error:e}=await supabase.from("schools").select("*").eq("owner_id",profile.id).maybeSingle();if(e){setError(e.message);return}setSchool(s);if(s){setSchoolForm({name:s.name||"",district:s.district||"",sector:s.sector||"",phone:s.phone||"",email:s.email||profile.email||"",registration_number:s.registration_number||"",representative_name:s.representative_name||""});setVacancyForm(x=>({...x,district:s.district||""}));const{data:v,error:ve}=await supabase.from("job_vacancies").select("*").eq("school_id",s.id).order("created_at",{ascending:false});if(ve)setError(ve.message);else setVacancies(v||[]);const ids=(v||[]).map(x=>x.id);if(ids.length){const{data:a,error:ae}=await supabase.from("job_applications").select("*,profiles!applicant_id(full_name,email,phone,district,subject,teaching_level),job_vacancies!vacancy_id(title,subject,district)").in("vacancy_id",ids).order("created_at",{ascending:false});if(ae)setError(ae.message);else setApplications(a||[])}else setApplications([])}}
 async function saveSchool(e){e.preventDefault();setError("");try{let documentPath=school?.document_path||null;if(documentFile){const ext=documentFile.name.split(".").pop().toLowerCase();documentPath=`${profile.id}/school-license-${Date.now()}.${ext}`;const{error:u}=await supabase.storage.from("verification-documents").upload(documentPath,documentFile);if(u)throw u}const payload={...schoolForm,owner_id:profile.id,document_path:documentPath,verification_status:"pending"};let q=school?supabase.from("schools").update(payload).eq("id",school.id):supabase.from("schools").insert(payload);const{error}=await q;if(error)throw error;setProfileOpen(false);await load()}catch(e){setError(e.message)}}
 async function createVacancy(e){e.preventDefault();const{error}=await supabase.from("job_vacancies").insert({...vacancyForm,school_id:school.id,status:"published"});if(error)setError(error.message);else{setOpen(false);load()}}
 async function updateApplication(id,status){const{error}=await supabase.from("job_applications").update({status}).eq("id",id);if(error)setError(error.message);else load()}
 async function closeVacancy(id){const{error}=await supabase.from("job_vacancies").update({status:"closed"}).eq("id",id);if(error)setError(error.message);else load()}
 const sc=e=>setSchoolForm({...schoolForm,[e.target.name]:e.target.value});const vc=e=>setVacancyForm({...vacancyForm,[e.target.name]:e.target.value});const filtered=selectedVacancy==="all"?applications:applications.filter(a=>a.vacancy_id===selectedVacancy);
 return <main className="dashboard"><section className="welcome"><div><small>School Dashboard</small><h1>{school?.name||profile?.full_name}</h1><p>{school?.verification_status||"Profile ntiruzuzwa"}</p></div><div className="schoolActions"><button className="outline" onClick={()=>setProfileOpen(true)}>{school?"Hindura School Profile":"Uzuza School Profile"}</button><button className="primary" disabled={school?.verification_status!=="verified"} onClick={()=>setOpen(true)}>+ Tangaza vacancy</button></div></section>{error&&<div className="warning">{error}</div>}<section className="metrics"><article><b>{vacancies.length}</b><span>Vacancies</span></article><article><b>{applications.length}</b><span>Applications</span></article><article><b>{applications.filter(x=>x.status==="interview").length}</b><span>Interviews</span></article></section>{school&&<section className="schoolSummary"><p><b>Akarere:</b> {school.district}</p><p><b>Telefone:</b> {school.phone||"-"}</p><p><b>Registration:</b> {school.registration_number||"-"}</p><p><b>Status:</b> {school.verification_status}</p></section>}<h2>Vacancies z'ikigo</h2><section className="list">{vacancies.length?vacancies.map(v=><article key={v.id}><div className="row"><div><h3>{v.title}</h3><p>{v.subject} · {v.district} · Deadline {v.deadline}</p></div><span className={`badge ${v.status==="published"?"verified":"pending"}`}>{v.status}</span></div>{v.status==="published"&&<button className="reject" onClick={()=>closeVacancy(v.id)}>Funga vacancy</button>}</article>):<div className="empty">Nta vacancy iratangazwa.</div>}</section><section className="toolbar"><h2>Abasabye akazi</h2><select value={selectedVacancy} onChange={e=>setSelectedVacancy(e.target.value)}><option value="all">Vacancies zose</option>{vacancies.map(v=><option key={v.id} value={v.id}>{v.title}</option>)}</select></section><section className="list">{filtered.length?filtered.map(a=><article key={a.id} className="applicationCard"><div className="row"><div><h3>{a.profiles?.full_name||"Applicant"}</h3><p>{a.profiles?.email} · {a.profiles?.phone||"Nta telefone"}</p></div><span className="badge pending">{a.status}</span></div><div className="applicationActions"><button className="outline" onClick={()=>updateApplication(a.id,"viewed")}>Viewed</button><button className="primary" onClick={()=>updateApplication(a.id,"shortlisted")}>Shortlist</button><button className="interview" onClick={()=>updateApplication(a.id,"interview")}>Interview</button><button className="approve" onClick={()=>updateApplication(a.id,"selected")}>Selected</button><button className="reject" onClick={()=>updateApplication(a.id,"rejected")}>Reject</button></div></article>):<div className="empty">Nta applications zirahari.</div>}</section>
 {profileOpen&&<div className="overlay"><form className="modal wide" onSubmit={saveSchool}><button type="button" className="close" onClick={()=>setProfileOpen(false)}>✕</button><h2>School Profile no Kwemezwa</h2><div className="formGrid"><label>Izina ry'ikigo<input name="name" value={schoolForm.name} onChange={sc} required/></label><label>Akarere<select name="district" value={schoolForm.district} onChange={e=>setSchoolForm({...schoolForm,district:e.target.value,sector:""})} required><option value="">Hitamo Akarere</option>{districts.map(d=><option key={d} value={d}>{d}</option>)}</select></label><label>Umurenge<select name="sector" value={schoolForm.sector} onChange={sc} disabled={!schoolForm.district} required><option value="">{schoolForm.district?"Hitamo Umurenge":"Banza uhitemo Akarere"}</option>{sectorsFor(schoolForm.district).map(s=><option key={s} value={s}>{s}</option>)}</select></label><label>Telefone<input name="phone" value={schoolForm.phone} onChange={sc} required/></label><label>Email<input name="email" type="email" value={schoolForm.email} onChange={sc} required/></label><label>Registration/Licence No<input name="registration_number" value={schoolForm.registration_number} onChange={sc} required/></label><label>Uhagarariye ikigo<input name="representative_name" value={schoolForm.representative_name} onChange={sc} required/></label><label>Licence cyangwa registration document<input type="file" accept=".pdf,.jpg,.jpeg,.png" onChange={e=>setDocumentFile(e.target.files?.[0]||null)} required={!school?.document_path}/></label></div><button className="primary full">Bika kandi usabe kwemezwa</button></form></div>}
 {open&&<div className="overlay"><form className="modal wide" onSubmit={createVacancy}><button type="button" className="close" onClick={()=>setOpen(false)}>✕</button><h2>Tangaza vacancy</h2><div className="formGrid"><label>Izina ry'umwanya<input name="title" value={vacancyForm.title} onChange={vc} required/></label><label>Isomo<input name="subject" value={vacancyForm.subject} onChange={vc} required/></label><label>Urwego<select name="teaching_level" value={vacancyForm.teaching_level} onChange={vc}>{["Nursery","Primary","Secondary","TVET"].map(x=><option key={x}>{x}</option>)}</select></label><label>Akarere<select name="district" value={vacancyForm.district} onChange={vc} required><option value="">Hitamo Akarere</option>{districts.map(d=><option key={d} value={d}>{d}</option>)}</select></label><label>Impamyabumenyi<input name="qualification" value={vacancyForm.qualification} onChange={vc}/></label><label>Uburambe<input name="minimum_experience" type="number" min="0" value={vacancyForm.minimum_experience} onChange={vc}/></label><label>Ubwoko bw'akazi<input name="employment_type" value={vacancyForm.employment_type} onChange={vc}/></label><label>Deadline<input name="deadline" type="date" value={vacancyForm.deadline} onChange={vc} required/></label><label className="wideField">Ibisobanuro<textarea name="description" value={vacancyForm.description} onChange={vc} required/></label></div><button className="primary full">Tangaza</button></form></div>}</main>}
function ChatModal({match,userId,messages,body,setBody,send,close,complete}){
 return <div className="overlay"><div className="modal wide chatModal"><button type="button" className="close" onClick={close}>✕</button><h2>Ubutumwa na {match.other?.full_name||"uwo mwahujwe"}</h2><div className="chatList">{messages.length?messages.map(m=><div key={m.id} className={`bubble ${m.sender_id===userId?"mine":"theirs"}`}><p>{m.body}</p><small>{new Date(m.created_at).toLocaleString()}</small></div>):<div className="empty">Nta butumwa burimo. Tangira ikiganiro.</div>}</div><form onSubmit={send} className="chatForm"><textarea value={body} onChange={e=>setBody(e.target.value)} placeholder="Andika ubutumwa..." maxLength="3000" required/><button className="primary">Ohereza</button></form><button className="approve full" onClick={complete}>✓ Nabonye permutation</button></div></div>
}
createRoot(document.getElementById("root")).render(<App/>);
